import {distribution} from './distribution-config.js';
import {fixtureSettings,stoneSettings} from './kitchen-settings.js?v=details-5';
import {TILE_ZONES,ensureSurfaces,setCabinetFinish,snapshotFinishes,restoreFinishes,PALETTES,applyPalette} from './finish-config.js?v=details-5';

export function mountFinishUI(host,{get,floor,change,review,lighting,capture,toast}){
 const comparisons=new WeakMap();let zone='primary';
 host.innerHTML=`<div class="finishIntro"><span class="eyebrow">MATERIAL STUDY</span><h2>See the finishes together.</h2><p>Real grain, tile joints and surface sheen. Choices apply to this floor of the selected design.</p></div>
 <div class="finishViews"><button data-review="family">Living room</button><button data-review="kitchen">Kitchen</button><button data-review="bath">Bathroom</button><button data-review="stove">Wood stove</button></div>
 <div class="finishViews detailViews" id="detailViews"><button data-review="sink">Sink &amp; faucet</button><button data-review="hardware">Handles &amp; edge</button><button data-review="back">Back French doors</button><button data-review="front">Front entry door</button><button data-review="vanity">Bathroom vanity</button><button data-review="dining">Dining table</button></div>
 <p class="note" id="detailBasis">Exterior doors: black. Interior door style and finish: not selected. Door profiles and fixtures are representative; the front door’s narrow window is provisionally on the north side.</p>
 <label class="field">Review lighting<select id="finishLighting"><option value="day">Neutral daylight</option><option value="evening">Warm evening</option><option value="night">Lights only</option></select></label>
 <section class="finishSection"><h3>Try a palette together</h3><div id="paletteChoices" class="paletteChoices"></div><p class="note">These change cabinets, paint and stone colors. Your floor, trim and tile sizes stay selected.</p></section>
 <section class="finishSection"><h3>01 / Wood flooring</h3><label class="field">Flooring product<select id="floorProduct"><option value="saguaro">Taverne Saguaro · French oak</option><option value="generic">Generic oak color study</option></select></label><div id="saguaroReference" class="productReference">${distribution.manufacturerSwatch?'<img src="assets/materials/saguaro-reference.jpg" alt="California Classics Taverne Saguaro manufacturer swatch">':''}<div><strong>Saguaro · TANR9974</strong><p>8 in wide · lengths up to 75 in<br>Wire brushed · low gloss</p><a href="https://californiaclassicsfloors.com/hardwood-flooring/Taverne/FrenchOak/Saguaro-flooring.aspx" target="_blank" rel="noopener">Manufacturer reference ↗</a></div></div><p id="saguaroNote" class="note">${distribution.manufacturerSwatch?'Photo-based approximation using the manufacturer’s swatch. Pattern and color variation need checking against your actual boards.':'Selected product reference only. This public preview uses freely licensed oak grain at 8-inch widths and lengths up to 75 inches; it is not a Saguaro color match.'}</p><label class="field">Oak tone<select id="floorFinish"><option value="#b99160">Natural oak</option><option value="#d4bd95">Pale oak</option><option value="#907354">Smoked oak</option></select></label><div class="grid2"><label class="field">Board width (in)<input id="boardWidth" type="number" min="3" max="12" step=".5"></label><label class="field">Sheen<select id="floorSheen"><option value="matte">Matte</option><option value="satin">Satin</option></select></label></div><label class="field">Boards run<select id="floorDirection"><option value="0">Front to back · E–W</option><option value="90">Side to side · N–S</option></select></label></section>
 <section class="finishSection"><h3>02 / Cabinets &amp; countertops</h3><label class="field">Cabinets on this floor<select id="cabinetFinish"><option value="#986b43">Natural oak</option><option value="#e9e7e0">Warm white paint</option><option value="#263335">Charcoal paint</option><option value="#64422d">Walnut tone on oak grain</option></select></label><label class="field">Cabinet sheen<select id="cabinetSheen"><option value="matte">Matte</option><option value="satin">Satin</option></select></label><label class="field">Countertop stone<select id="counterFinish"><option value="#efede7">Warm white stone</option><option value="#454747">Charcoal stone</option><option value="#b6aca0">Warm limestone tone</option></select></label><label class="field">Countertop sheen<select id="counterSheen"><option value="honed">Honed</option><option value="polished">Polished</option></select></label><label class="field" id="detailEdgeField">Kitchen counter edge<select id="detailCounterEdge"><option value="eased">Eased edge</option><option value="bevel">Small bevel</option><option value="half-bullnose">Half bullnose</option><option value="miter">Mitered thick edge</option></select></label></section>
 <section class="finishSection" id="fixtureStudy"><h3>Kitchen / Details to compare</h3><div class="grid2"><label class="field">Handle finish<select id="detailHardware"><option value="dark">Matte black</option><option value="steel">Brushed steel</option><option value="brass">Brushed brass</option></select></label><label class="field">Handle shape<select id="detailPullStyle"><option value="bar">Round bar pull</option><option value="knob">Round knob</option></select></label></div><div class="grid2"><label class="field">Faucet finish<select id="detailFaucetFinish"><option value="steel">Brushed steel</option><option value="dark">Matte black</option><option value="brass">Brushed brass</option></select></label><label class="field">Faucet shape<select id="detailFaucetStyle"><option value="arc">High arc pull-down</option><option value="square">Squared pull-down</option></select></label></div><label class="field">Undermount sink<select id="detailSinkFinish"><option value="steel">Stainless steel</option><option value="white">White ceramic</option><option value="dark">Dark composite</option></select></label><p class="note">Independent kitchen finish studies, with the current sink cutout and cabinet dimensions. Circle a detail and attach the actual product to match it.</p></section>
 <section class="finishSection"><h3>03 / Trim &amp; ceiling</h3><label class="field">Trim package<select id="trimFinish"><option value="white">Painted white · flat stock</option><option value="oak">Natural oak · clear finish</option><option value="smoked">Smoked oak tone</option><option value="walnut">Dark walnut tone on oak</option></select></label><p class="note">5 in baseboards and 2½ in door/window casings. Wood colors are studies; final species and stain samples are still open. Interior doors are not selected; trim choices do not set their finish.</p><div class="ceilingChoice"><strong>Main room: painted drywall</strong><span>Tongue-and-groove removed. Vault geometry retained.</span></div></section>
 <section class="finishSection"><h3>04 / Paint</h3><div class="paintPresets"><button data-paint="#eeeae1" style="--swatch:#eeeae1">Warm white</button><button data-paint="#ffffff" style="--swatch:#ffffff">Clean white</button><button data-paint="#c4beb0" style="--swatch:#c4beb0">Putty</button><button data-paint="#a7afa0" style="--swatch:#a7afa0">Sage</button></div><label class="field">Wall paint<input type="color" id="wallColor"></label><label class="field">Paint sheen<select id="paintSheen"><option value="matte">Matte</option><option value="eggshell">Eggshell</option><option value="satin">Satin</option></select></label></section>
 <section class="finishSection"><h3>05 / Tile &amp; grout</h3><label class="field">Tile area<select id="tileZone"></select></label><div class="tilePreview" id="tilePreview" aria-label="Tile and grout color samples"><span>Tile</span><span>Grout</span></div><div class="grid2"><label class="field">Tile color<input type="color" id="tileColor"></label><label class="field">Grout color<input type="color" id="groutColor"></label></div><label class="field">Tile size<select id="tileFormat"><option value="24,12">12 × 24 in</option><option value="24,24">24 × 24 in</option><option value="12,12">12 × 12 in</option><option value="12,3">3 × 12 in</option><option value="2,2">2 × 2 in mosaic</option></select></label><div class="grid2"><label class="field">Joint<select id="groutJoint"><option value="0.0625">1/16 in</option><option value="0.125">1/8 in</option><option value="0.1875">3/16 in</option><option value="0.25">1/4 in</option><option value="0.375">3/8 in</option></select></label><label class="field">Layout<select id="tilePattern"><option value="stack">Stacked</option><option value="offset">Half offset</option></select></label></div><label class="field">Tile sheen<select id="tileSheen"><option value="matte">Matte</option><option value="satin">Satin</option></select></label><p class="note">Formats are visual studies. Confirm the selected product’s permitted joint, offset and wet-area suitability.</p></section>
 <section class="finishSection"><h3>Compare &amp; keep</h3><div class="grid2"><button id="finishSaveA">Save option A</button><button id="finishCompare" disabled>Compare A / B</button></div><p class="note" id="finishCompareStatus" role="status">Save A, change your finishes, then compare. Camera, light and exposure stay fixed. A/B lasts for this session.</p><button id="finishCapture" class="finishWide">Save room image</button><button id="finishSchedule" class="finishWide">Download finish schedule</button></section>
 <p class="note">Saguaro uses a manufacturer photo reference; other materials use scanned oak and stone with representative colors. Confirm paint, sheen and color using physical samples in the room. <a href="assets/materials/credits.txt" target="_blank" rel="noopener">Texture sources ↗</a></p>`;
 const el=id=>host.querySelector('#'+id),update=(comparison=false)=>{const c=comparisons.get(get());if(c&&!comparison&&c.showing==='A')c.showing='B';change();renderValues();};
 for(const [key,p] of Object.entries(PALETTES)){const button=document.createElement('button');button.dataset.palette=key;const title=document.createElement('strong'),description=document.createElement('span');title.textContent=p.name;description.textContent=p.description;button.append(title,description);button.onclick=()=>{applyPalette(get(),key);update();toast(p.name+' applied. Flooring and trim kept.');};el('paletteChoices').append(button);}
 el('detailCounterEdge').onchange=e=>{get().kitchen.stone??={};get().kitchen.stone.edge=e.target.value;update();};
 el('detailHardware').onchange=e=>{get().kitchen.hardware=e.target.value;update();};
 for(const [id,key] of [['detailPullStyle','pullStyle'],['detailFaucetFinish','faucetFinish'],['detailFaucetStyle','faucetStyle'],['detailSinkFinish','sinkFinish']])el(id).onchange=e=>{get().kitchen.fixtures={...fixtureSettings(get().kitchen),[key]:e.target.value};update();};
 el('floorProduct').onchange=e=>{const s=ensureSurfaces(get());s.floorProduct=e.target.value;if(s.floorProduct==='saguaro'){s.boardWidth=8;s.boardLength=75;s.floorSheen='matte';}update();};
 el('trimFinish').onchange=e=>{ensureSurfaces(get()).trim=e.target.value;update();};
 for(const button of host.querySelectorAll('[data-review]'))button.onclick=()=>review(button.dataset.review);
 el('finishLighting').onchange=e=>{lighting(e.target.value);};
 for(const [id,key] of [['floorFinish','floor'],['counterFinish','counter'],['wallColor','wall']])el(id).onchange=e=>{get().finishes[key]=e.target.value;update();};
 el('cabinetFinish').onchange=e=>{setCabinetFinish(get(),e.target.value);update();};
 for(const key of ['floorSheen','cabinetSheen','counterSheen','paintSheen'])el(key).onchange=e=>{ensureSurfaces(get())[key]=e.target.value;if(key==='counterSheen'&&get().kitchen){get().kitchen.stone??={};get().kitchen.stone.finish=e.target.value;}update();};
 el('boardWidth').onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<3||n>12){renderValues();return;}ensureSurfaces(get()).boardWidth=n;update();};
 el('floorDirection').onchange=e=>{ensureSurfaces(get()).direction=Number(e.target.value);update();};
 for(const b of host.querySelectorAll('[data-paint]'))b.onclick=()=>{get().finishes.wall=b.dataset.paint;update();};
 el('tileZone').onchange=e=>{zone=e.target.value;renderValues();};
 for(const [id,key] of [['tileColor','color'],['groutColor','grout'],['groutJoint','joint'],['tilePattern','pattern'],['tileSheen','sheen']])el(id).onchange=e=>{ensureSurfaces(get()).tiles[zone][key]=key==='joint'?Number(e.target.value):e.target.value;update();};
 el('tileFormat').onchange=e=>{const [w,h]=e.target.value.split(',').map(Number),t=ensureSurfaces(get()).tiles[zone];t.width=w;t.height=h;update();};
 el('finishSaveA').onclick=()=>{comparisons.set(get(),{a:snapshotFinishes(get()),showing:'B'});renderValues();toast('Option A saved. Change finishes to create B.');};
 el('finishCompare').onclick=()=>{const c=comparisons.get(get());if(!c)return;if(c.showing==='B'){c.b=snapshotFinishes(get());restoreFinishes(get(),c.a);c.showing='A';}else{restoreFinishes(get(),c.b);c.showing='B';}update(true);};
 el('finishCapture').onclick=()=>capture();
 el('finishSchedule').onclick=()=>{const s=ensureSurfaces(get()),rows=[['Area','Selection','Details'],['Flooring',s.floorProduct==='saguaro'?'California Classics Taverne Saguaro TANR9974':el('floorFinish').selectedOptions[0].textContent,`${s.boardWidth} in boards; ${s.floorProduct==='saguaro'?'random lengths up to 75 in; ':''}${s.direction===0?'E–W':'N–S'}; ${s.floorSheen}`],['Trim',el('trimFinish').selectedOptions[0].textContent,'5 in base; 2.5 in casing; assumed flat-stock profiles'],[floor()==='main'?'Main-room ceiling':'Basement ceiling','Painted drywall',floor()==='main'?'T&G removed; vault retained':'Flat ceiling'],['Cabinets',el('cabinetFinish').selectedOptions[0].textContent,s.cabinetSheen],['Counter',el('counterFinish').selectedOptions[0].textContent,s.counterSheen],['Wall paint',get().finishes.wall,s.paintSheen],['Exterior doors','Black','Front entry and rear French doors; profiles and hardware remain provisional'],['Interior doors','Not selected','Style and finish are open'],...(floor()==='main'?[['Kitchen counter edge',stoneSettings(get().kitchen).edge,stoneSettings(get().kitchen).edge==='miter'?stoneSettings(get().kitchen).edgeDrop+' in drop':''],['Kitchen handles',get().kitchen.hardware,fixtureSettings(get().kitchen).pullStyle],['Kitchen faucet',fixtureSettings(get().kitchen).faucetFinish,fixtureSettings(get().kitchen).faucetStyle],['Kitchen sink',fixtureSettings(get().kitchen).sinkFinish,'Representative undermount bowl']]:[]),...Object.entries(s.tiles).filter(([k])=>floor()==='basement'?k==='basement':['primary','shower','showerFloor','shared','laundry'].includes(k)).map(([k,t])=>[TILE_ZONES[k],t.color,`${t.height} x ${t.width} in; ${t.pattern}; ${t.joint} in grout ${t.grout}; ${t.sheen}`]),['Basis',distribution.manufacturerSwatch?'Saguaro manufacturer photo; other finishes representative':'Public copy: illustrative CC0 oak; no manufacturer swatch','Confirm physical samples; other product selections are open.']];const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');download(new Blob([csv],{type:'text/csv'}),'brines-'+floor()+'-finish-study.csv');};
 function renderValues(){
  const state=get(),s=ensureSurfaces(state),b=floor()==='basement';if(b&&zone!=='basement')zone='basement';if(!b&&zone==='basement')zone='primary';
  el('tileZone').replaceChildren(...Object.entries(TILE_ZONES).filter(([k])=>b?k==='basement':k!=='basement').map(([k,label])=>new Option(label,k)));el('tileZone').value=zone;
  for(const [id,key] of [['floorFinish','floor'],['cabinetFinish','cabinet'],['counterFinish','counter'],['wallColor','wall']])el(id).value=state.finishes[key];
  el('floorProduct').value=s.floorProduct;el('trimFinish').value=s.trim;const product=s.floorProduct==='saguaro';el('saguaroReference').hidden=!product;el('saguaroNote').hidden=!product;el('floorFinish').closest('label').hidden=product;el('boardWidth').disabled=product;el('floorSheen').disabled=product;host.querySelector('.ceilingChoice').hidden=b;
  for(const key of ['boardWidth','floorSheen','cabinetSheen','counterSheen','paintSheen'])el(key).value=s[key];el('floorDirection').value=s.direction;el('finishLighting').value=state.daylight;
  for(const id of ['fixtureStudy','detailViews','detailBasis','detailEdgeField'])el(id).hidden=b;
  if(!b&&state.kitchen){const f=fixtureSettings(state.kitchen);el('detailCounterEdge').value=stoneSettings(state.kitchen).edge;el('detailHardware').value=state.kitchen.hardware;for(const [id,key] of [['detailPullStyle','pullStyle'],['detailFaucetFinish','faucetFinish'],['detailFaucetStyle','faucetStyle'],['detailSinkFinish','sinkFinish']])el(id).value=f[key];}
  const t=s.tiles[zone];for(const [id,key] of [['tileColor','color'],['groutColor','grout'],['groutJoint','joint'],['tilePattern','pattern'],['tileSheen','sheen']])el(id).value=t[key];el('tileFormat').value=t.width+','+t.height;
  el('tilePreview').style.setProperty('--tile',t.color);el('tilePreview').style.setProperty('--grout',t.grout);
  const c=comparisons.get(state);el('finishCompare').disabled=!c;if(c)el('finishCompareStatus').textContent=c.b?'Showing option '+c.showing+'. Camera, light and exposure are unchanged.':'Option A saved. Change finishes, then compare.';else el('finishCompareStatus').textContent='Save A, change your finishes, then compare. Camera, light and exposure stay fixed. A/B lasts for this session.';
  host.querySelector('[data-review="family"]').hidden=b;host.querySelector('[data-review="kitchen"]').hidden=b;host.querySelector('[data-review="stove"]').hidden=b;
 }
 renderValues();return {render:renderValues};
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
